// Get icon by product name or category
export const getProductIcon = (productName: string, category: string) => {
  // Try to match by category first
  if (ProductIcons[category as keyof typeof ProductIcons]) {
    return ProductIcons[category as keyof typeof ProductIcons];
  }

  // Try to match by product name
  const nameMatch = Object.keys(ProductIcons).find(key =>
    productName.toLowerCase().includes(key.toLowerCase())
  );

  if (nameMatch) {
    return ProductIcons[nameMatch as keyof typeof ProductIcons];
  }

  // Default to Other icon
  return ProductIcons.Other;
};

// Get category color
export const getCategoryColor = (category: string): string => {
  const colors: Record<string, string> = {
    ChatGPT: '#10a37f',
    Claude: '#d97757',
    Gemini: '#4285f4',
    Spotify: '#1db954',
    Cursor: '#000000',
    GitHub: '#24292e',
    Midjourney: '#000000',
    Canva: '#00c4cc',
    YouTube: '#ff0000',
    Netflix: '#e50914',
    'Apple Music': '#fa243c',
    'Google Drive': '#4285f4',
    QuillBot: '#6c63ff',
    'Leonardo AI': '#667eea',
    'Suno AI': '#ff6b6b',
    Other: '#6e6e73',
  };

  return colors[category] || colors.Other;
};
